Giá trị của a là gì?

def safe(v):
    try:
        n = int(v)
        if n == 0:
            return "Z"
        return str(12 // n)
    except ValueError:
        return "E"
    finally:
        print("F", end="")
a = safe("3")
b = safe("bad")
c = safe("0")

